CREATE TABLE IF NOT EXISTS social_destinations (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN ('telegram','vk','x','webhook')),endpoint TEXT,account_ref TEXT,encrypted_token TEXT NOT NULL,is_enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS publication_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,page_id INTEGER NOT NULL REFERENCES cms_pages(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','processing','partial','published','failed','cancelled')),scheduled_at TEXT NOT NULL,destination_ids TEXT NOT NULL DEFAULT '[]',attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 5,next_attempt_at TEXT,last_error TEXT,locked_at TEXT,lock_token TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_publication_due ON publication_jobs(status,next_attempt_at,scheduled_at);
CREATE TABLE IF NOT EXISTS publication_deliveries (id INTEGER PRIMARY KEY AUTOINCREMENT,job_id INTEGER NOT NULL REFERENCES publication_jobs(id) ON DELETE CASCADE,destination_id INTEGER NOT NULL REFERENCES social_destinations(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,http_status INTEGER,response_excerpt TEXT,error_message TEXT,published_ref TEXT,last_attempt_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(job_id,destination_id));
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.2.0');
